INSERT INTO `researches` (`id`, `title`, `header_image`, `description`, `objective`, `status`, `lead_researcher`, `created_at`) VALUES
(5, 'Revitalisasi Lahan TSTH2 melalui Sistem Agroforestri Berbasis Ekosistem', '1776766249_research.jpg', 'TSTH2 menginisiasi revitalisasi lahan melalui penerapan sistem agroforestry, sebuah pendekatan ilmiah yang menggabungkan tanaman hutan dengan pertanian dalam satu sistem produksi. Sistem ini dirancang tidak hanya untuk meningkatkan produktivitas, tetapi juga untuk memulihkan fungsi ekologis lahan secara berkelanjutan.\r\nProgram ini dilaksanakan bersama petani lokal sebagai mitra utama, dengan beberapa komoditas, seperti kopi, jeruk, tomat, kol, dan cabai dalam pola tanam multi-strata. Kombinasi ini memungkinkan pemanfaatan ruang tumbuh yang optimal. Tanaman tahunan berperan sebagai peneduh dan penyangga ekosistem, sementara tanaman hortikultura memberikan hasil yang lebih cepat sebagai sumber pendapatan harian.', 'Salah satu aspek penting dari pendekatan ini adalah upaya pemulihan kualitas tanah, khususnya pada lahan eks-eucalyptus yang umumnya mengalami penurunan kandungan unsur hara dan struktur tanah yang kurang optimal. Melalui diversifikasi tanaman dan sistem pengelolaan ramah lingkungan, sistem agroforestri mampu meningkatkan kandungan bahan organik, memperbaiki siklus hara, serta meningkatkan kapasitas tanah dalam menyimpan air.\r\nDari sisi ekosistem, agroforestri dapat berkontribusi pada peningkatan keanekaragaman hayati, stabilisasi mikroklimat, serta pengurangan risiko erosi dan degradasi lahan. Interaksi antar tanaman dan organisme tanah menciptakan ekosistem yang lebih tahan terhadap tekanan lingkungan, bahkan perubahan iklim.\r\nSelain itu, dari sisi sosial-ekonomi, agroforestri dapat memberikan dampak yang signifikan bagi petani. Diversifikasi tanaman memungkinkan sumber pendapatan yang lebih beragam dan stabil dibandingkan sistem monokultur. Petani tidak tergantung pada satu jenis tanaman saja, tetapi masih memiliki beberapa komoditas dengan siklus panen yang berbeda, sehingga risiko ekonomi dapat diminimalisir.', 'Sedang Berjalan', 'Sri Fatmawati Ph.D', '2026-04-21 10:10:49'),
(6, 'Presisi Riset Benih Kentang di TSTH2: Evaluasi Adaptasi dan Kinerja Lintas Agroekosistem', '1776766540_research.jpg', 'Produksi benih dasar kentang (G0) bukan sekadar tahap awal perbenihan, tetapi fondasi dari sistem pertanian yang kuat dan berkelanjutan. Di balik 20 calon varietas baru yang kini siap uji multilokasi, tersimpan proses riset panjang yang memastikan setiap benih mampu beradaptasi di berbagai kondisi lingkungan.\r\nUji multilokasi menjadi kunci untuk menguji adaptabilitas varietas di berbagai ekosistem. Hal ini memastikan benih dapat memberikan hasil yang stabil dan tahan terhadap tekanan lingkungan. Uji ini juga dapat diperkuat dengan uji keunggulan dan karakterisasi tanaman, tujuannya adalah menggali potensi produktivitas, kualitas umbi, hingga ketahanan terhadap hama dan penyakit.\r\nProses aklimatisasi dari kultur in vitro ke kondisi lapangan juga menjadi penentu utama keberhasilan produksi G0. Pada tahap ini, benih diuji untuk beradaptasi secara fisiologis, memastikan kualitas tetap terjaga saat masuk ke tahap produksi massal.\r\nDengan capaian produksi 3.060 knol benih F1 dan 28.836 knol benih dasar (G0), riset ini menegaskan bahwa benih unggul lahir dari integrasi ilmu, ketelitian, dan inovasi. Riset ini adalah langkah strategis menuju peningkatan produktivitas kentang nasional dan kemandirian sektor pertanian.', 'Riset ini adalah langkah strategis menuju peningkatan produktivitas kentang nasional dan kemandirian sektor pertanian.', 'Selesai', 'Sri Fatmawati Ph.D', '2026-04-21 10:15:40');

